    getSuppliers: function() {
        const stored = localStorage.getItem('zeyvo_business_suppliers_v1');
        if (stored) {
            try {
                const list = JSON.parse(stored);
                if (Array.isArray(list) && list.length > 0) return list;
            } catch (e) {
                console.error("Error parsing suppliers", e);
            }
        }
        const defaults = this.getDefaultSuppliers();
        this.saveSuppliers(defaults);
        return defaults;
    },

    saveSuppliers: function(list) {
        localStorage.setItem('zeyvo_business_suppliers_v1', JSON.stringify(list));
    },

