        if (accSelect) this.financeTxFilterAcc = accSelect.value;
        const catSelect = document.getElementById('bizFinanceFilterModalCat');
        if (catSelect) this.financeTxFilterCat = catSelect.value;

        this.financeTxPage = 1;
